#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef double cost;
/* Jonker-Volgenant dense LAP. c: n*n row-major. x[i]=col of row i, y[j]=row of col j */
int lapjv(int n, const cost *c, int *x, int *y){
    int *free_=malloc(n*sizeof(int)), *collist=malloc(n*sizeof(int)), *matches=calloc(n,sizeof(int)), *pred=malloc(n*sizeof(int));
    cost *d=malloc(n*sizeof(cost)), *v=malloc(n*sizeof(cost));
    int i,j,k,numfree=0,f,i0,low,up,last,endofpath,j1,j2,loopcnt,prvnumfree;
    cost min=0,h,umin,usubmin,v2;
    for(j=n-1;j>=0;j--){
        min=c[j]; int imin=0;
        for(i=1;i<n;i++) if(c[(size_t)i*n+j]<min){min=c[(size_t)i*n+j];imin=i;}
        v[j]=min;
        if(++matches[imin]==1){x[imin]=j;y[j]=imin;} else y[j]=-1;
    }
    for(i=0;i<n;i++){
        if(matches[i]==0) free_[numfree++]=i;
        else if(matches[i]==1){
            j1=x[i]; min=DBL_MAX; const cost*ci=c+(size_t)i*n;
            for(j=0;j<n;j++) if(j!=j1){ h=ci[j]-v[j]; if(h<min) min=h;}
            v[j1]-=min;
        }
    }
    loopcnt=0;
    do{
        loopcnt++;
        k=0; prvnumfree=numfree; numfree=0;
        while(k<prvnumfree){
            i=free_[k++]; const cost*ci=c+(size_t)i*n;
            umin=ci[0]-v[0]; j1=0; usubmin=DBL_MAX; j2=-1;
            for(j=1;j<n;j++){
                h=ci[j]-v[j];
                if(h<usubmin){
                    if(h>=umin){usubmin=h;j2=j;}
                    else{usubmin=umin;umin=h;j2=j1;j1=j;}
                }
            }
            i0=y[j1];
            if(umin<usubmin) v[j1]=v[j1]-(usubmin-umin);
            else if(i0>=0){j1=j2;i0=y[j2];}
            x[i]=j1; y[j1]=i;
            if(i0>=0){
                if(umin<usubmin) free_[--k]=i0;
                else free_[numfree++]=i0;
            }
        }
    }while(loopcnt<2);
    for(f=0;f<numfree;f++){
        int freerow=free_[f]; const cost*cf=c+(size_t)freerow*n;
        for(j=n-1;j>=0;j--){ d[j]=cf[j]-v[j]; pred[j]=freerow; collist[j]=j;}
        low=0; up=0; int unassignedfound=0; last=0; endofpath=-1;
        do{
            if(up==low){
                last=low-1;
                min=d[collist[up++]];
                for(k=up;k<n;k++){
                    j=collist[k]; h=d[j];
                    if(h<=min){
                        if(h<min){up=low;min=h;}
                        collist[k]=collist[up]; collist[up++]=j;
                    }
                }
                for(k=low;k<up;k++) if(y[collist[k]]<0){endofpath=collist[k];unassignedfound=1;break;}
            }
            if(!unassignedfound){
                j1=collist[low++]; i=y[j1]; const cost*ci=c+(size_t)i*n;
                h=ci[j1]-v[j1]-min;
                for(k=up;k<n;k++){
                    j=collist[k]; v2=ci[j]-v[j]-h;
                    if(v2<d[j]){
                        pred[j]=i;
                        if(v2==min){
                            if(y[j]<0){endofpath=j;unassignedfound=1;break;}
                            else{collist[k]=collist[up];collist[up++]=j;}
                        }
                        d[j]=v2;
                    }
                }
            }
        }while(!unassignedfound);
        for(k=0;k<=last;k++){ j1=collist[k]; v[j1]=v[j1]+d[j1]-min; }
        do{
            i=pred[endofpath]; y[endofpath]=i; j1=endofpath; endofpath=x[i]; x[i]=j1;
        }while(i!=freerow);
    }
    free(free_);free(collist);free(matches);free(pred);free(d);free(v);
    return 0;
}
