#include <stdlib.h>
#include <string.h>
#include <float.h>
/* adjacency */
typedef struct { int *col; int cnt, cap; } Row;
static void addedge(Row *r, int j){
    for(int k=0;k<r->cnt;k++) if(r->col[k]==j) return;
    if(r->cnt==r->cap){ r->cap=r->cap*2+4; r->col=realloc(r->col,r->cap*sizeof(int)); }
    r->col[r->cnt++]=j;
}
/* heap of (key,col) */
typedef struct { double k; int j; } HE;
static void hpush(HE *h,int *sz,double k,int j){
    int i=(*sz)++; while(i>0){int p=(i-1)/2; if(h[p].k<=k) break; h[i]=h[p]; i=p;} h[i].k=k; h[i].j=j;
}
static HE hpop(HE *h,int *sz){
    HE top=h[0]; HE last=h[--(*sz)]; int i=0,n=*sz;
    while(1){int l=2*i+1; if(l>=n) break; int r=l+1; int m=(r<n&&h[r].k<h[l].k)?r:l; if(h[m].k>=last.k) break; h[i]=h[m]; i=m;}
    if(n>0) h[i]=last; return top;
}
static void select_k(const double *row, int n, int K, int *out, double *tmp, int *idx){
    /* simple: partial selection via nth-element-like quickselect on indices */
    for(int j=0;j<n;j++) idx[j]=j;
    int lo=0, hi=n-1, k=K-1;
    while(lo<hi){
        double piv=row[idx[(lo+hi)/2]]; int i=lo,j=hi;
        while(i<=j){ while(row[idx[i]]<piv) i++; while(row[idx[j]]>piv) j--; if(i<=j){int t=idx[i];idx[i]=idx[j];idx[j]=t;i++;j--;} }
        if(k<=j) hi=j; else if(k>=i) lo=i; else break;
    }
    for(int t=0;t<K;t++) out[t]=idx[t];
}
/* returns 0 on success; x[i] = assigned column */
int solve(int n, const double *c, int K, int *x){
    if(K>n) K=n;
    Row *rows=calloc(n,sizeof(Row));
    int *idx=malloc(n*sizeof(int)), *sel=malloc(n*sizeof(int));
    double *colbuf=malloc(n*sizeof(double));
    for(int i=0;i<n;i++){
        select_k(c+(size_t)i*n,n,K,sel,NULL,idx);
        rows[i].cap=2*K; rows[i].col=malloc(rows[i].cap*sizeof(int)); rows[i].cnt=0;
        for(int t=0;t<K;t++) rows[i].col[rows[i].cnt++]=sel[t];
    }
    /* column-wise kNN */
    for(int j=0;j<n;j++){
        for(int i=0;i<n;i++) colbuf[i]=c[(size_t)i*n+j];
        select_k(colbuf,n,K,sel,NULL,idx);
        for(int t=0;t<K;t++) addedge(&rows[sel[t]],j);
    }
    int *y=malloc(n*sizeof(int)), *pred=malloc(n*sizeof(int)), *done=malloc(n*sizeof(int)), *touched=malloc(n*sizeof(int));
    double *v=calloc(n,sizeof(double)), *d=malloc(n*sizeof(double));
    HE *heap=malloc(sizeof(HE)*(size_t)(n*(K*4+n)+16));
    size_t heapcap=(size_t)(n*(K*4+n)+16);
    int ret=0;
    for(int outer=0; outer<50; outer++){
        for(int i=0;i<n;i++) x[i]=-1;
        for(int j=0;j<n;j++){ y[j]=-1; d[j]=DBL_MAX; done[j]=0; }
        /* v kept from previous outer iteration? must restart with valid duals; reset */
        for(int j=0;j<n;j++) v[j]=0;
        int fail=0;
        for(int f=0; f<n && !fail; f++){
            /* Dijkstra from row f */
            int sz=0, nt=0, endj=-1; double dmin=0;
            Row *r=&rows[f]; const double *cf=c+(size_t)f*n;
            for(int t=0;t<r->cnt;t++){int j=r->col[t]; double h=cf[j]-v[j]; if(d[j]==DBL_MAX) touched[nt++]=j; if(h<d[j]){d[j]=h;pred[j]=f;hpush(heap,&sz,h,j);} }
            int *fin=idx; int nf=0;
            while(sz>0){
                HE e=hpop(heap,&sz); int j=e.j;
                if(done[j]||e.k>d[j]) continue;
                done[j]=1; fin[nf++]=j; dmin=d[j];
                if(y[j]<0){ endj=j; break; }
                int i=y[j]; const double *ci=c+(size_t)i*n; double ui=ci[j]-v[j];
                Row *ri=&rows[i];
                for(int t=0;t<ri->cnt;t++){int jj=ri->col[t]; if(done[jj]) continue; double h=dmin+ci[jj]-v[jj]-ui;
                    if(d[jj]==DBL_MAX) touched[nt++]=jj;
                    if(h<d[jj]){ d[jj]=h; pred[jj]=i; if((size_t)sz<heapcap) hpush(heap,&sz,h,jj);} }
            }
            if(endj<0){ fail=1; break; }
            for(int t=0;t<nf;t++){int j=fin[t]; v[j]+=d[j]-dmin;}
            for(int t=0;t<nt;t++){int j=touched[t]; d[j]=DBL_MAX; done[j]=0;}
            /* augment */
            int j=endj;
            while(1){ int i=pred[j]; y[j]=i; int pj=x[i]; x[i]=j; if(i==f) break; j=pj; }
        }
        if(fail){
            /* increase density: add next K columns per row */
            K*=2; if(K>n) K=n;
            for(int i=0;i<n;i++){ select_k(c+(size_t)i*n,n,K,sel,NULL,idx); for(int t=0;t<K;t++) addedge(&rows[i],sel[t]); }
            free(heap); heapcap=0; for(int i=0;i<n;i++) heapcap+=rows[i].cnt; heapcap=heapcap*2+n+16; heap=malloc(sizeof(HE)*heapcap);
            continue;
        }
        /* optimality check over full matrix */
        int viol=0;
        for(int i=0;i<n;i++){
            const double *ci=c+(size_t)i*n; double ui=ci[x[i]]-v[x[i]];
            for(int j=0;j<n;j++){ if(ci[j]-v[j] < ui - 1e-12){ addedge(&rows[i],j); viol++; } }
        }
        if(!viol){ ret=0; goto end; }
        free(heap); heapcap=0; for(int i=0;i<n;i++) heapcap+=rows[i].cnt; heapcap=heapcap*2+n+16; heap=malloc(sizeof(HE)*heapcap);
    }
    ret=1;
end:
    for(int i=0;i<n;i++) free(rows[i].col);
    free(rows);free(idx);free(sel);free(colbuf);free(y);free(pred);free(done);free(touched);free(v);free(d);free(heap);
    return ret;
}
