#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef struct { int *col; int cnt, cap; } Row;
static inline void addedge_nochk(Row *r, int j){
    if(r->cnt==r->cap){ r->cap=r->cap*2+4; r->col=realloc(r->col,r->cap*sizeof(int)); }
    r->col[r->cnt++]=j;
}
typedef struct { double k; int j; } HE;
typedef struct { HE *h; int sz, cap; } Heap;
static inline void hpush(Heap *H,double k,int j){
    if(H->sz==H->cap){ H->cap=H->cap*2+16; H->h=realloc(H->h,H->cap*sizeof(HE)); }
    HE *h=H->h; int i=H->sz++;
    while(i>0){int p=(i-1)>>1; if(h[p].k<=k) break; h[i]=h[p]; i=p;} h[i].k=k; h[i].j=j;
}
static inline HE hpop(Heap *H){
    HE *h=H->h; HE top=h[0]; HE last=h[--H->sz]; int i=0,n=H->sz;
    while(1){int l=2*i+1; if(l>=n) break; int r=l+1; int m=(r<n&&h[r].k<h[l].k)?r:l; if(h[m].k>=last.k) break; h[i]=h[m]; i=m;}
    if(n>0) h[i]=last; return top;
}
/* select K smallest of key[0..n) into out (indices) */
static void select_k(const double *key, int n, int K, int *out, int *idx){
    for(int j=0;j<n;j++) idx[j]=j;
    int lo=0, hi=n-1, k=K-1;
    while(lo<hi){
        double piv=key[idx[(lo+hi)/2]]; int i=lo,j=hi;
        while(i<=j){ while(key[idx[i]]<piv) i++; while(key[idx[j]]>piv) j--; if(i<=j){int t=idx[i];idx[i]=idx[j];idx[j]=t;i++;j--;} }
        if(k<=j) hi=j; else if(k>=i) lo=i; else break;
    }
    memcpy(out,idx,K*sizeof(int));
}
/* mark: per-row bitmap of present edges (n*n bytes) */
int solve(int n, const double *c, int K, int *x){
    if(K>n) K=n;
    Row *rows=calloc(n,sizeof(Row));
    unsigned char *has=calloc((size_t)n*n,1);
    int *idx=malloc(n*sizeof(int)), *sel=malloc(n*sizeof(int));
    double *buf=malloc(n*sizeof(double));
    for(int i=0;i<n;i++){
        select_k(c+(size_t)i*n,n,K,sel,idx);
        rows[i].cap=3*K; rows[i].col=malloc(rows[i].cap*sizeof(int));
        for(int t=0;t<K;t++){ addedge_nochk(&rows[i],sel[t]); has[(size_t)i*n+sel[t]]=1; }
    }
    for(int j=0;j<n;j++){
        for(int i=0;i<n;i++) buf[i]=c[(size_t)i*n+j];
        select_k(buf,n,K,sel,idx);
        for(int t=0;t<K;t++){ int i=sel[t]; if(!has[(size_t)i*n+j]){ has[(size_t)i*n+j]=1; addedge_nochk(&rows[i],j);} }
    }
    int *y=malloc(n*sizeof(int)), *pred=malloc(n*sizeof(int)), *done=calloc(n,sizeof(int)), *touched=malloc(n*sizeof(int));
    int *fin=malloc(n*sizeof(int)), *freeq=malloc(n*sizeof(int)*2), *vrows=malloc(n*sizeof(int));
    char *rvis=calloc(n,1);
    double *v=calloc(n,sizeof(double)), *d=malloc(n*sizeof(double));
    Heap H={malloc(1024*sizeof(HE)),0,1024};
    for(int i=0;i<n;i++) x[i]=-1;
    for(int j=0;j<n;j++){ y[j]=-1; d[j]=DBL_MAX; }
    int nfree=0; for(int i=0;i<n;i++) freeq[nfree++]=i;
    int ret=0, guard=0;
    while(1){
        while(nfree>0){
            int f=freeq[--nfree];
            if(x[f]>=0) continue;
            H.sz=0; int nt=0, endj=-1, nf=0, nv=0; double dmin=0;
            {
                Row *r=&rows[f]; const double *cf=c+(size_t)f*n;
                vrows[nv++]=f; rvis[f]=1;
                for(int t=0;t<r->cnt;t++){int j=r->col[t]; double h=cf[j]-v[j]; if(d[j]==DBL_MAX) touched[nt++]=j; if(h<d[j]){d[j]=h;pred[j]=f;hpush(&H,h,j);} }
            }
            while(H.sz>0){
                HE e=hpop(&H); int j=e.j;
                if(done[j]||e.k>d[j]) continue;
                done[j]=1; fin[nf++]=j; dmin=d[j];
                if(y[j]<0){ endj=j; break; }
                int i=y[j]; const double *ci=c+(size_t)i*n; double ui=ci[j]-v[j];
                vrows[nv++]=i; rvis[i]=1;
                Row *ri=&rows[i];
                for(int t=0;t<ri->cnt;t++){int jj=ri->col[t]; if(done[jj]) continue; double h=dmin+ci[jj]-v[jj]-ui;
                    if(d[jj]==DBL_MAX) touched[nt++]=jj;
                    if(h<d[jj]){ d[jj]=h; pred[jj]=i; hpush(&H,h,jj);} }
            }
            if(endj>=0){
                for(int t=0;t<nf;t++){int j=fin[t]; v[j]+=d[j]-dmin;}
                for(int t=0;t<nt;t++){int j=touched[t]; d[j]=DBL_MAX; done[j]=0;}
                for(int t=0;t<nv;t++) rvis[vrows[t]]=0;
                int j=endj;
                while(1){ int i=pred[j]; y[j]=i; int pj=x[i]; x[i]=j; if(i==f) break; j=pj; }
            } else {
                for(int t=0;t<nt;t++){int j=touched[t]; d[j]=DBL_MAX; done[j]=0;}
                /* Hall violation: expand visited rows with more edges by reduced cost */
                for(int t=0;t<nv;t++){
                    int i=vrows[t]; rvis[i]=0;
                    const double *ci=c+(size_t)i*n; unsigned char *hi=has+(size_t)i*n;
                    for(int j=0;j<n;j++) buf[j]= hi[j]? DBL_MAX : ci[j]-v[j];
                    int kk=K; select_k(buf,n,kk,sel,idx);
                    double ui = x[i]>=0 ? ci[x[i]]-v[x[i]] : -DBL_MAX;
                    int bad=0;
                    for(int s=0;s<kk;s++){int j=sel[s]; if(hi[j]) continue; hi[j]=1; addedge_nochk(&rows[i],j); if(buf[j]<ui) bad=1;}
                    if(bad && x[i]>=0){ y[x[i]]=-1; x[i]=-1; freeq[nfree++]=i; }
                }
                freeq[nfree++]=f;
            }
        }
        /* full optimality check */
        int viol=0;
        for(int i=0;i<n;i++){
            const double *ci=c+(size_t)i*n; double ui=ci[x[i]]-v[x[i]]; unsigned char *hi=has+(size_t)i*n;
            int bad=0;
            for(int j=0;j<n;j++){ if(ci[j]-v[j] < ui - 1e-13 && !hi[j]){ hi[j]=1; addedge_nochk(&rows[i],j); bad=1; } }
            if(bad){ y[x[i]]=-1; x[i]=-1; freeq[nfree++]=i; viol++; }
        }
        if(!viol) break;
        if(++guard>1000){ ret=1; break; }
    }
    for(int i=0;i<n;i++) free(rows[i].col);
    free(rows);free(has);free(idx);free(sel);free(buf);free(y);free(pred);free(done);free(touched);
    free(fin);free(freeq);free(vrows);free(rvis);free(v);free(d);free(H.h);
    return ret;
}
