#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <math.h>
typedef struct { double k; int j; } HE;
typedef struct { HE *h; int sz, cap; } Heap;
static inline void hpush(Heap *H,double k,int j){
    if(H->sz==H->cap){ H->cap=H->cap*2+16; H->h=realloc(H->h,H->cap*sizeof(HE)); }
    HE *h=H->h; int i=H->sz++;
    while(i>0){int p=(i-1)>>1; if(h[p].k<=k) break; h[i]=h[p]; i=p;} h[i].k=k; h[i].j=j;
}
static inline HE hpop(Heap *H){
    HE *h=H->h; HE top=h[0]; HE last=h[--H->sz]; int i=0,n=H->sz;
    while(1){int l=2*i+1; if(l>=n) break; int r=l+1; int m=(r<n&&h[r].k<h[l].k)?r:l; if(h[m].k>=last.k) break; h[i]=h[m]; i=m;}
    if(n>0) h[i]=last; return top;
}
typedef struct { int *col; int cnt, cap; } Row;
static inline void addedge(Row *r, int j){
    if(r->cnt==r->cap){ r->cap=r->cap*2+8; r->col=realloc(r->col,r->cap*sizeof(int)); }
    r->col[r->cnt++]=j;
}
static int cmpd(const void*a,const void*b){double x=*(double*)a,y=*(double*)b;return (x>y)-(x<y);}

/* Exact assignment (min-cost perfect matching) on dense n x n cost c. x[i]=column.
   Returns 0 on success. K = target average edges per row. */
int solve(int n, const double *c, int K, int *x){
    int ret=0;
    unsigned char *has=calloc((size_t)n*n,1);
    Row *rows=calloc(n,sizeof(Row));
    /* threshold from sample */
    int ns=4096; double *smp=malloc(ns*sizeof(double));
    unsigned long long s=88172645463325252ULL; size_t N=(size_t)n*n;
    for(int t=0;t<ns;t++){ s^=s<<13; s^=s>>7; s^=s<<17; smp[t]=c[s%N]; }
    qsort(smp,ns,sizeof(double),cmpd);
    int q=(int)((double)K/n*ns); if(q>=ns) q=ns-1; if(q<0) q=0;
    double thr=smp[q]; free(smp);
    for(int i=0;i<n;i++){
        const double *ci=c+(size_t)i*n; unsigned char *hi=has+(size_t)i*n;
        Row *r=&rows[i]; r->cap=2*K+8; r->col=malloc(r->cap*sizeof(int));
        for(int j=0;j<n;j++) if(ci[j]<=thr){ hi[j]=1; addedge(r,j); }
    }
    int *y=malloc(n*sizeof(int));
    double *v=malloc(n*sizeof(double));
    for(int j=0;j<n;j++){ y[j]=-1; }
    /* greedy matching to guarantee a perfect matching exists in sparse graph */
    {
        for(int i=0;i<n;i++){
            const double *ci=c+(size_t)i*n; Row *r=&rows[i];
            int bj=-1; double bc=DBL_MAX;
            for(int t=0;t<r->cnt;t++){int j=r->col[t]; if(y[j]<0 && ci[j]<bc){bc=ci[j];bj=j;}}
            if(bj<0){
                for(int j=0;j<n;j++) if(y[j]<0 && ci[j]<bc){bc=ci[j];bj=j;}
                has[(size_t)i*n+bj]=1; addedge(r,bj);
            }
            y[bj]=i;
        }
    }
    /* column reduction on sparse graph: v_j = min over edges in column; assign */
    for(int j=0;j<n;j++){ v[j]=DBL_MAX; y[j]=-1; }
    int *argm=malloc(n*sizeof(int));
    for(int i=0;i<n;i++){ const double *ci=c+(size_t)i*n; Row *r=&rows[i];
        for(int t=0;t<r->cnt;t++){int j=r->col[t]; if(ci[j]<v[j]){v[j]=ci[j];argm[j]=i;}} }
