static int spfa(int n, Row *rows, const int *x, const int *y, double *v, int *inq, int *cntr, int *qq){
    memset(inq,0,n*sizeof(int)); memset(cntr,0,n*sizeof(int));
    int qh=0, qt=0, qn=0;
    for(int i=0;i<n;i++){ qq[qt++]=i; inq[i]=1; qn++; } if(qt==n+1) qt=0;
    while(qn>0){
        int i=qq[qh]; if(++qh==n+1) qh=0; qn--; inq[i]=0;
        Row *r=&rows[i]; int jx=x[i]; double base=v[jx]-r->src[jx];
        for(int t=0;t<r->cnt;t++){ int j=r->col[t]; double nv=base+r->w[t];
            if(nv<v[j]){ v[j]=nv; int k=y[j];
                if(!inq[k]){ if(++cntr[k]>n) return 1; inq[k]=1; qq[qt]=k; if(++qt==n+1) qt=0; qn++; } } }
    }
    return 0;
}

/* auction: process rows in fl[0..nf); prices p (as cost addition: profit = -(c+p)) */
static int auction(Row *rows, int *x, int *y, double *p, int *fl, int nf, double eps, long *budget){
    while(nf>0){
        int i=fl[--nf]; Row *r=&rows[i];
        double w1=DBL_MAX,w2=DBL_MAX; int j1=-1;
        const int *col=r->col; const double *w=r->w; int cnt=r->cnt;
        for(int t=0;t<cnt;t++){ int j=col[t]; double h=w[t]+p[j];
            if(h<w2){ if(h<w1){w2=w1;w1=h;j1=j;} else w2=h; } }
        if(w2==DBL_MAX) w2=w1+1.0;
        p[j1]+= (w2-w1)+eps;
        int o=y[j1]; y[j1]=i; x[i]=j1;
        if(o>=0){ x[o]=-1; fl[nf++]=o; }
        if(--(*budget)<0) return 1;
    }
    return 0;
}

static int cmpd(const void*a,const void*b){double x=*(double*)a,y=*(double*)b;return (x>y)-(x<y);}

int solve(int n, const double *c, int K, int *x){
#ifdef DBG
    double T0=now();
#endif
    int ret=0;
    Row *rows=calloc(n,sizeof(Row));
    int ns=2048; double *smp=malloc(ns*sizeof(double));
    unsigned long long s=88172645463325252ULL; size_t N=(size_t)n*n;
    for(int t=0;t<ns;t++){ s^=s<<13; s^=s>>7; s^=s<<17; smp[t]=c[s%N]; }
    qsort(smp,ns,sizeof(double),cmpd);
    int q=(int)((double)K/n*ns); if(q>=ns) q=ns-1; if(q<0) q=0;
    double thr=smp[q]; free(smp);
    int *y=malloc(n*sizeof(int));
    for(int j=0;j<n;j++) y[j]=-1;
    for(int i=0;i<n;i++){
        const double *ci=c+(size_t)i*n;
        Row *r=&rows[i]; r->cap=2*K+16; r->col=malloc(r->cap*sizeof(int)); r->w=malloc(r->cap*sizeof(double)); r->src=ci;
        int cnt=0; int *col=r->col; double *w=r->w;
        for(int j=0;j<n;j++){ double cc=ci[j]; if(cc<=thr){ if(cnt==r->cap){ r->cnt=cnt; r->cap*=2; r->col=col=realloc(col,r->cap*sizeof(int)); r->w=w=realloc(w,r->cap*sizeof(double)); } col[cnt]=j; w[cnt]=cc; cnt++; } }
        r->cnt=cnt;
        /* greedy to guarantee perfect matching exists */
        int bj=-1; double bc=DBL_MAX;
        for(int t=0;t<cnt;t++){int j=col[t]; if(y[j]<0 && w[t]<bc){bc=w[t];bj=j;}}
        if(bj<0){ for(int j=0;j<n;j++) if(y[j]<0 && ci[j]<bc){bc=ci[j];bj=j;} addedge(r,bj); }
        y[bj]=i;
    }
    for(int j=0;j<n;j++) y[j]=-1;
    for(int i=0;i<n;i++) x[i]=-1;
#ifdef DBG
    double T1=now(); LOG("setup %.2f ",(T1-T0)*1e3);
#endif
    double *p=calloc(n,sizeof(double)), *v=malloc(n*sizeof(double));
    int *fl=malloc(n*sizeof(int)), *inq=malloc(n*sizeof(int)), *cntr=malloc(n*sizeof(int)), *qq=malloc((n+1)*sizeof(int));
    long budget=(long)n*20000;
    double eps=EPS0;
    int nf=0; for(int i=0;i<n;i++) fl[nf++]=i;
    if(auction(rows,x,y,p,fl,nf,eps,&budget)){ ret=1; goto end; }
    int iter=0;
    while(1){
        if(++iter>500){ ret=1; goto end; }
        if(eps>EPSF){
            /* next phase: unassign rows violating eps-CS */
            eps/=EDIV; nf=0;
            for(int i=0;i<n;i++){ Row *r=&rows[i]; double m=DBL_MAX;
                for(int t=0;t<r->cnt;t++){ double h=r->w[t]+p[r->col[t]]; if(h<m) m=h; }
                int j=x[i]; if(r->src[j]+p[j] > m+eps){ y[j]=-1; x[i]=-1; fl[nf++]=i; } }
            if(auction(rows,x,y,p,fl,nf,eps,&budget)){ ret=1; goto end; }
            continue;
        }
        for(int j=0;j<n;j++) v[j]=-p[j];
        if(spfa(n,rows,x,y,v,inq,cntr,qq)){
            LOG("negcycle eps %g ",eps);
            eps=eps/EDIV*EDIV; /* force another phase below */
            eps/=EDIV; nf=0;
            for(int i=0;i<n;i++){ Row *r=&rows[i]; double m=DBL_MAX;
                for(int t=0;t<r->cnt;t++){ double h=r->w[t]+p[r->col[t]]; if(h<m) m=h; }
                int j=x[i]; if(r->src[j]+p[j] > m+eps){ y[j]=-1; x[i]=-1; fl[nf++]=i; } }
            if(eps<1e-15){ ret=1; goto end; }
            if(auction(rows,x,y,p,fl,nf,eps,&budget)){ ret=1; goto end; }
            continue;
        }
        /* dense check */
        nf=0;
        for(int i=0;i<n;i++){
            const double *ci=c+(size_t)i*n; double ui=ci[x[i]]-v[x[i]]-1e-14;
            int bad=0;
            for(int j=0;j<n;j++) bad |= (ci[j]-v[j] < ui);
            if(bad){
                Row *r=&rows[i];
                for(int j=0;j<n;j++) if(ci[j]-v[j] < ui && !hasedge(r,j)) addedge(r,j);
                fl[nf++]=i;
            }
        }
        LOG("viol %d ",nf);
        if(!nf) break;
        for(int k=0;k<nf;k++){ int i=fl[k]; y[x[i]]=-1; x[i]=-1; }
        if(auction(rows,x,y,p,fl,nf,eps,&budget)){ ret=1; goto end; }
    }
end:
#ifdef DBG
    LOG("total %.2f ret %d\n",(now()-T0)*1e3,ret);
#endif
    for(int i=0;i<n;i++){ free(rows[i].col); free(rows[i].w); }
    free(rows); free(y); free(p); free(v); free(fl); free(inq); free(cntr); free(qq);
    return ret;
}
