{"command": "cat > cyc.c <<'EOF'
/* Bellman-Ford (SPFA) on column potentials with negative cycle canceling.
   Edge: col x[i] -> col j via row i, weight c_ij - c_{i,x_i}. Feasible v: v[j] <= v[x_i] + c_ij - c_{i x_i} + TOL.
   Returns 0 when feasible potentials found (assignment optimal on sparse graph), 1 on give-up. */
#ifndef BFTOL
#define BFTOL 1e-14
#endif
static int pred_has_cycle(int n, const int *predrow, const int *x, int *mark, int *start){
    /* mark: 0 unvisited, else visit id */
    memset(mark,0,n*sizeof(int));
    for(int s=0;s<n;s++){
        if(mark[s]) continue;
        int j=s;
        while(j>=0 && !mark[j]){ mark[j]=s+1; int i=predrow[j]; j = i>=0 ? x[i] : -1; }
        if(j>=0 && mark[j]==s+1){ *start=j; return 1; }
    }
    return 0;
}
static int bf_cancel(int n, Row *rows, int *x, int *y, double *v, long *ncancel){
    int *inq=malloc(n*sizeof(int)), *qq=malloc((n+1)*sizeof(int)), *predrow=malloc(n*sizeof(int)), *mark=malloc(n*sizeof(int));
    int *cr=malloc(n*sizeof(int)), *cc=malloc(n*sizeof(int));
    int ret=0; long rounds=0;
    for(;;){
        if(++rounds>2000){ ret=1; break; }
        for(int j=0;j<n;j++) predrow[j]=-1;
        memset(inq,0,n*sizeof(int));
        int qh=0, qt=0, qn=0;
        for(int i=0;i<n;i++){ qq[qt++]=i; inq[i]=1; qn++; } if(qt==n+1) qt=0;
        long relax=0, nextchk=n; int cyc=0, cstart=-1;
        while(qn>0){
            int i=qq[qh]; if(++qh==n+1) qh=0; qn--; inq[i]=0;
            Row *r=&rows[i]; int jx=x[i]; double base=v[jx]-r->src[jx]+BFTOL;
            const int *col=r->col; const double *w=r->w; int cnt=r->cnt;
            for(int t=0;t<cnt;t++){ int j=col[t]; double nv=base+w[t];
                if(nv<v[j]){ v[j]=nv-BFTOL; predrow[j]=i; relax++; int k=y[j];
                    if(!inq[k]){ inq[k]=1; qq[qt]=k; if(++qt==n+1) qt=0; qn++; } } }
            if(relax>=nextchk){ nextchk=relax+n; if(pred_has_cycle(n,predrow,x,mark,&cstart)){ cyc=1; break; } }
        }
        if(!cyc){ if(pred_has_cycle(n,predrow,x,mark,&cstart)) cyc=1; }
        if(!cyc) break;
        /* collect cycle */
        int m=0, j=cstart;
        do{ int i=predrow[j]; cr[m]=i; cc[m]=j; m++; j=x[i]; }while(j!=cstart && m<=n);
        if(m>n){ ret=1; break; }
        for(int k=0;k<m;k++){ x[cr[k]]=cc[k]; y[cc[k]]=cr[k]; }
        (*ncancel)++;
    }
    free(inq);free(qq);free(predrow);free(mark);free(cr);free(cc);
    return ret;
}
