/* Parallel asynchronous auction. obj[j] = (float price bits << 32) | (uint32 owner) */
#include <stdatomic.h>
typedef struct {
    Row *rows; int n; _Atomic unsigned long long *obj; float eps;
    atomic_int nfree, scanners, tid, abort_; int *stacks; long budget; int doscan;
} PA;
static inline float pr_of(unsigned long long w){ unsigned int b=(unsigned int)(w>>32); float f; memcpy(&f,&b,4); return f; }
static inline int ow_of(unsigned long long w){ return (int)(unsigned int)(w&0xffffffffu); }
static inline unsigned long long pack(float p,int o){ unsigned int b; memcpy(&b,&p,4); return ((unsigned long long)b<<32)|(unsigned int)o; }
static inline void best2p(const Row *r, const float *pp, float *w1o, float *w2o, int *j1o){
    int cnt=r->cnt; const int *col=r->col; const float *w=r->wf;
    __m256 m1=_mm256_set1_ps(FLT_MAX), m2=m1; __m256i i1=_mm256_set1_epi32(-1);
    int t=0;
    for(;t+8<=cnt;t+=8){
        __m256i id=_mm256_loadu_si256((const __m256i*)(col+t));
        __m256 h=_mm256_add_ps(_mm256_loadu_ps(w+t), _mm256_i32gather_ps(pp,id,8));
        __m256 lt=_mm256_cmp_ps(h,m1,_CMP_LT_OQ);
        m2=_mm256_blendv_ps(_mm256_min_ps(m2,h),m1,lt);
        m1=_mm256_blendv_ps(m1,h,lt);
        i1=_mm256_castps_si256(_mm256_blendv_ps(_mm256_castsi256_ps(i1),_mm256_castsi256_ps(id),lt));
    }
    float a1[8],a2[8]; int ai[8];
    _mm256_storeu_ps(a1,m1); _mm256_storeu_ps(a2,m2); _mm256_storeu_si256((__m256i*)ai,i1);
    int kb=0; for(int k=1;k<8;k++) if(a1[k]<a1[kb]) kb=k;
    float w1=a1[kb], w2=a2[kb]; int j1=ai[kb];
    for(int k=0;k<8;k++) if(k!=kb){ if(a1[k]<w2) w2=a1[k]; }
    for(;t<cnt;t++){ int j=col[t]; float h=w[t]+pp[2*j];
        if(h<w2){ if(h<w1){w2=w1;w1=h;j1=j;} else w2=h; } }
    *w1o=w1; *w2o=w2; *j1o=j1;
}
static void pa_worker(void *vc, int lo, int hi){
    PA *A=vc; int n=A->n; int id=atomic_fetch_add(&A->tid,1);
    int *st=A->stacks+(size_t)id*n; int ns=0;
    _Atomic unsigned long long *obj=A->obj; const float *pp=(const float*)obj+1;
    float eps=A->eps; long bud=A->budget/NT;
    if(A->doscan){
        int added=0;
        for(int i=lo;i<hi;i++){
            Row *r=&A->rows[i];
            /* find assigned object of i: scan row edges for owner==i */
            int jx=-1; float cx=0;
            float m=FLT_MAX;
            for(int t=0;t<r->cnt;t++){ int j=r->col[t]; unsigned long long wv=atomic_load_explicit(&obj[j],memory_order_relaxed);
                float h=r->wf[t]+pr_of(wv); if(h<m) m=h; if(ow_of(wv)==i){ jx=j; cx=h; } }
            if(jx<0){ st[ns++]=i; added++; continue; }
            if(cx > m+eps){
                unsigned long long wv=atomic_load(&obj[jx]);
                if(ow_of(wv)==i && atomic_compare_exchange_strong(&obj[jx],&wv,pack(pr_of(wv),-1))){ st[ns++]=i; added++; }
            }
        }
        atomic_fetch_add(&A->nfree,added);
        atomic_fetch_sub(&A->scanners,1);
    } else {
        for(int i=lo;i<hi;i++) st[ns++]=i;
    }
    for(;;){
        while(ns>0){
            int i=st[--ns]; Row *r=&A->rows[i];
            for(;;){
                float w1,w2; int j1;
                best2p(r,pp,&w1,&w2,&j1);
                if(w2==FLT_MAX) w2=w1+1.0f;
                /* new absolute price */
                unsigned long long old=atomic_load(&obj[j1]);
                float oldp=pr_of(old);
                float newp=oldp+(w2-w1)+eps;
                /* w1 computed with possibly stale price of j1: recompute w1 with oldp */
                if(--bud<0){ atomic_store(&A->abort_,1); return; }
                int ok=0;
                while(1){
                    /* bid level: c_ij1 + newp = w2 + eps with c from w1 - stale p; use direct cost */
                    if(atomic_compare_exchange_weak(&obj[j1],&old,pack(newp,i))){ ok=1; break; }
