        if(h<w2){ if(h<w1){w2=w1;w1=h;t1=t;} else w2=h; } }
    *w2o=w2; *t1o=t1;
}
static void pa_scan(void *vc, int lo, int hi){
    PA *A=vc; int n=A->n; int id=atomic_fetch_add(&A->tid,1);
    int *st=A->stacks+(size_t)id*n; int ns=0;
    _Atomic unsigned long long *obj=A->obj; float eps=A->eps;
    for(int i=lo;i<hi;i++){
        Row *r=&A->rows[i]; int jx=A->x[i];
        if(jx<0){ st[ns++]=i; continue; }
        float m=FLT_MAX, cx=0;
        for(int t=0;t<r->cnt;t++){ int j=r->col[t]; float h=r->wf[t]+pr_of(obj[j]); if(h<m) m=h; if(j==jx) cx=h; }
        if(cx > m+eps){ obj[jx]=pack(pr_of(obj[jx]),-1); st[ns++]=i; }
    }
    A->cnts[id]=ns;
    atomic_fetch_add(&A->nfree,ns);
}
static void pa_run(void *vc, int lo, int hi){
    PA *A=vc; int n=A->n; int id=atomic_fetch_add(&A->tid,1);
    int *st=A->stacks+(size_t)id*n; int ns=A->cnts[id];
    _Atomic unsigned long long *obj=A->obj; const float *pp=((const float*)obj)+1;
    float eps=A->eps; long bud=A->budget/NT;
    for(;;){
        while(ns>0){
            int i=st[--ns]; Row *r=&A->rows[i];
            for(;;){
                float w2; int t1;
                best2p(r,pp,&w2,&t1);
                int j1=r->col[t1];
                if(w2==FLT_MAX) w2=r->wf[t1]+pp[2*j1]+1.0f;
                float newp=w2+eps-r->wf[t1];
                if(--bud<0){ atomic_store(&A->abort_,1); return; }
                unsigned long long old=atomic_load_explicit(&obj[j1],memory_order_relaxed);
                int ok=0;
                while(pr_of(old)<newp){
                    if(atomic_compare_exchange_weak(&obj[j1],&old,pack(newp,i))){ ok=1; break; }
                }
                if(!ok) continue;
                int o=ow_of(old);
                if(o>=0) st[ns++]=o; else atomic_fetch_sub(&A->nfree,1);
                break;
            }
        }
        if(atomic_load(&A->abort_)) return;
        if(atomic_load(&A->nfree)==0) return;
        _mm_pause();
    }
}
/* parallel auction phase. if all: start from all rows free. returns 1 on failure */
static int pauction(Row *rows, int n, int *x, int *y, float *p, float eps, int all, long *budget,
                    _Atomic unsigned long long *obj, int *stacks){
    PA A; A.rows=rows; A.n=n; A.obj=obj; A.eps=eps; A.stacks=stacks; A.budget=*budget; A.x=x;
    int cnts[NT]; A.cnts=cnts;
    atomic_init(&A.nfree,0); atomic_init(&A.abort_,0);
    for(int j=0;j<n;j++) obj[j]=pack(p[j], all? -1 : y[j]);
    if(all){
        for(int t=0;t<NT;t++){ int lo=(long)n*t/NT, hi=(long)n*(t+1)/NT; cnts[t]=0; for(int i=lo;i<hi;i++) stacks[(size_t)t*n+cnts[t]++]=i; }
        atomic_store(&A.nfree,n);
    } else { atomic_init(&A.tid,0); pfor(n,pa_scan,&A); }
    if(atomic_load(&A.nfree)>0){ atomic_init(&A.tid,0); pfor(n,pa_run,&A); }
    if(atomic_load(&A.abort_)) return 1;
    for(int i=0;i<n;i++) x[i]=-1;
    for(int j=0;j<n;j++){ unsigned long long w=obj[j]; p[j]=pr_of(w); int o=ow_of(w); y[j]=o; if(o>=0) x[o]=j; }
    for(int i=0;i<n;i++) if(x[i]<0) return 1;
    return 0;
}
