typedef struct { Row *rows; const float *p; const int *fl; int *bj; float *bp; float eps; } JB;
static void jac_bids(void *vc, int lo, int hi){
    JB *J=vc;
    for(int k=lo;k<hi;k++){
        Row *r=&J->rows[J->fl[k]]; float w1,w2; int j1;
        best2(r,J->p,&w1,&w2,&j1);
        if(w2==FLT_MAX) w2=w1+1.0f;
        J->bj[k]=j1; J->bp[k]=J->p[j1]+(w2-w1)+J->eps;
    }
}
#ifndef JTH
#define JTH 64
#endif
static int auction_j(Row *rows, int n, int *x, int *y, float *p, int *fl, int nf, float eps, long *budget){
    static int *bj=0,*win=0,*fl2=0; static float *bp=0,*best=0; static int cap=0;
    if(cap<n){ free(bj);free(win);free(fl2);free(bp);free(best); bj=malloc(n*4);win=malloc(n*4);fl2=malloc(n*4);bp=malloc(n*4);best=malloc(n*4); cap=n; for(int j=0;j<n;j++) win[j]=-1; }
    JB J={rows,p,fl,bj,bp,eps};
    while(nf>=JTH){
        J.fl=fl; pfor(nf,jac_bids,&J);
        int touched=0;
        for(int k=0;k<nf;k++){ int j=bj[k]; if(win[j]<0 || bp[k]>best[j]){ if(win[j]<0) fl2[n-1-touched++]=j; win[j]=k; best[j]=bp[k]; } }
        int nf2=0;
        for(int k=0;k<nf;k++){ int j=bj[k]; if(win[j]!=k) fl2[nf2++]=fl[k]; }
        for(int t=0;t<touched;t++){ int j=fl2[n-1-t]; int k=win[j]; int i=fl[k]; int o=y[j];
            p[j]=best[j]; y[j]=i; x[i]=j; if(o>=0){ x[o]=-1; fl2[nf2++]=o; } win[j]=-1; }
        /* note: fl2 low part (losers+displaced) and high part (touched objs) cannot overlap since nf2+touched<=n */
        memcpy(fl,fl2,nf2*sizeof(int)); nf=nf2;
        *budget-=touched; if(*budget<0) return 1;
    }
    return auction(rows,x,y,p,fl,nf,eps,budget);
}
